                    w = "1/6 * safezoneW";
                    h = "1/6 * safezoneH";
                    colorBackground[] = { 0, 0, 0, 0.1 };
                };
            };
        };
    };

    class controls
    {
        // populate with whatever other controls you are using in the actual dialog.
    };
};
```

You would then execute the dialog the normal way:

```sqf
createDialog "rscTileExample";
```

